  useEffect(()=>()=>{
   if(initial)void request('/api/browser/init-guide',{method:'POST',body:{hidden:true}}).catch(()=>{});
  },[initial,init.step,init.complete]);
 const hudTask=state.tasks?.find(t=>t.id===hudContext?.task_id);
